class Solution {
public:
    string largestPalindromic(string num) {
        int cnt[10] = {};
        for (char c : num) cnt[c - '0']++;

        int pairs = 0;
        for (int d = 0; d <= 9; d++) pairs += cnt[d] / 2;

        int mid = -1;
        for (int d = 9; d >= 0; d--) {
            if (cnt[d] % 2 == 1) { mid = d; break; }
        }

        bool hasNonZeroPair = false;
        for (int d = 9; d >= 1; d--) {
            if (cnt[d] / 2 > 0) { hasNonZeroPair = true; break; }
        }

        if (!hasNonZeroPair) {
            if (mid >= 0) return string(1, '0' + mid);
            return "0";
        }

        int len = 2 * pairs + (mid >= 0 ? 1 : 0);
        string res(len, '0');
        int pos = 0;
        for (int d = 9; d >= 0; d--) {
            int p = cnt[d] / 2;
            for (int i = 0; i < p; i++) {
                res[pos] = '0' + d;
                res[len - 1 - pos] = '0' + d;
                pos++;
            }
        }
        if (mid >= 0) {
            res[pos] = '0' + mid;
        }

        return res;
    }
};
